import React, { useState, useEffect } from 'react';
import { Modal, Button, Form } from 'react-bootstrap';

const PatientModal = ({ show, onHide, onSave, patientData }) => {
  const isEditMode = !!patientData;

  const initialFormData = {
    fullName: '',
    dob: '',
    email: '',
    glucose: '',
    haemoglobin: '',
    cholesterol: '',
    remarks: ''
  };

  const [formData, setFormData] = useState(initialFormData);
  const [errors, setErrors] = useState({});
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analyzeError, setAnalyzeError] = useState(null);
  const [currentStep, setCurrentStep] = useState(1);

  useEffect(() => {
    if (show) {
      if (patientData) {
        setFormData({ ...patientData });
      } else {
        setFormData(initialFormData);
      }
      setErrors({});
      setAnalyzeError(null);
      setCurrentStep(1);
    }
  }, [show, patientData]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });

    if (errors[name]) {
      setErrors({ ...errors, [name]: null });
    }
  };

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    setAnalyzeError(null);

    try {
      const response = await fetch('http://127.0.0.1:5000/analyze', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          full_name: formData.fullName,
          date_of_birth: formData.dob,
          glucose: formData.glucose,
          haemoglobin: formData.haemoglobin,
          cholesterol: formData.cholesterol
        })
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Failed to analyze data');
      }

      const reportString = data.health_report 
        ? JSON.stringify(data.health_report, null, 2) 
        : data.analysis;

      setFormData(prev => ({ ...prev, remarks: reportString }));
    } catch (err) {
      setAnalyzeError(err.message);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const validate = () => {
    const newErrors = {};
    const today = new Date().toISOString().split('T')[0];

    if (!formData.fullName.trim()) {
      newErrors.fullName = 'Full name is required';
    }

    if (!formData.email) {
      newErrors.email = 'Email is required';
    } else if (!/^\S+@\S+\.\S+$/.test(formData.email)) {
      newErrors.email = 'Email format is invalid';
    }

    if (!formData.dob) {
      newErrors.dob = 'Date of birth is required';
    } else if (formData.dob > today) {
      newErrors.dob = 'Date of birth cannot be in the future';
    }

    if (!formData.glucose || Number(formData.glucose) <= 0) {
      newErrors.glucose = 'Glucose must be positive';
    }

    if (!formData.haemoglobin || Number(formData.haemoglobin) <= 0) {
      newErrors.haemoglobin = 'Haemoglobin must be positive';
    }

    if (!formData.cholesterol || Number(formData.cholesterol) <= 0) {
      newErrors.cholesterol = 'Cholesterol must be positive';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleNextStep = () => {
    if (validate()) {
      setCurrentStep(2);
      if (!formData.remarks) {
        handleAnalyze();
      }
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (validate()) {
      onSave(formData);
    }
  };

  const renderHealthReport = () => {
    if (!formData.remarks && !isAnalyzing && !analyzeError) {
      return <p className="text-gray-500 text-center py-8">No analysis available.</p>;
    }

    let report;
    try {
      report = JSON.parse(formData.remarks);
    } catch (e) {
      return <p className="text-gray-700 whitespace-pre-wrap">{formData.remarks}</p>;
    }

    const getRiskBadge = (level) => {
      switch(level) {
        case 'HIGH': return <span className="bg-red-100 text-red-800 px-3 py-1 rounded-full text-xs font-bold tracking-wide">HIGH RISK</span>;
        case 'MODERATE': return <span className="bg-yellow-100 text-yellow-800 px-3 py-1 rounded-full text-xs font-bold tracking-wide">MODERATE RISK</span>;
        case 'LOW': return <span className="bg-green-100 text-green-800 px-3 py-1 rounded-full text-xs font-bold tracking-wide">LOW RISK</span>;
        default: return <span className="bg-gray-100 text-gray-800 px-3 py-1 rounded-full text-xs font-bold tracking-wide">UNKNOWN</span>;
      }
    };

    return (
      <div className="space-y-6">
        <div className="flex justify-between items-start border-b border-gray-100 pb-4">
          <div>
            <h4 className="text-lg font-bold text-gray-800 flex items-center gap-2">
              <span className="text-purple-600">✨</span> AI Health Report
            </h4>
            <p className="text-sm text-gray-500 mt-1">Generated by Gemini based on provided vitals.</p>
          </div>
          {getRiskBadge(report.risk_level)}
        </div>

        <div>
          <h5 className="text-sm font-bold text-gray-700 uppercase tracking-wider mb-2">Clinical Summary</h5>
          <p className="text-gray-700 text-sm leading-relaxed bg-blue-50/50 p-4 rounded-lg border border-blue-100">
            {report.clinical_summary}
          </p>
        </div>

        {report.identified_risks && report.identified_risks.length > 0 && (
          <div>
            <h5 className="text-sm font-bold text-red-700 uppercase tracking-wider mb-2 flex items-center gap-2">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
              Identified Risks
            </h5>
            <ul className="list-disc pl-5 space-y-1">
              {report.identified_risks.map((risk, idx) => (
                <li key={idx} className="text-gray-700 text-sm">{risk}</li>
              ))}
            </ul>
          </div>
        )}

        {report.recommendations && report.recommendations.length > 0 && (
          <div>
            <h5 className="text-sm font-bold text-green-700 uppercase tracking-wider mb-2 flex items-center gap-2">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
              Recommendations
            </h5>
            <ul className="list-disc pl-5 space-y-1">
              {report.recommendations.map((rec, idx) => (
                <li key={idx} className="text-gray-700 text-sm">{rec}</li>
              ))}
            </ul>
          </div>
        )}

        {report.follow_up && (
          <div className="bg-orange-50 p-4 rounded-lg border border-orange-100">
            <h5 className="text-sm font-bold text-orange-800 uppercase tracking-wider mb-1">Follow Up Required</h5>
            <p className="text-orange-900 text-sm">{report.follow_up}</p>
          </div>
        )}

        <div className="flex justify-end pt-2">
           <Button variant="link" onClick={handleAnalyze} disabled={isAnalyzing} className="text-xs text-purple-600 p-0 hover:text-purple-800">
             ↺ Re-run Analysis
           </Button>
        </div>
      </div>
    );
  };

  return (
    <Modal show={show} onHide={onHide} backdrop="static" keyboard={false} size="lg" centered>
      <Modal.Header closeButton className="border-b border-gray-100 px-6 py-4">
        <Modal.Title className="text-xl font-bold text-gray-800">
          {isEditMode ? 'Edit Patient' : 'Add New Patient'}
        </Modal.Title>
      </Modal.Header>

      <Form onSubmit={handleSubmit}>
        <Modal.Body className="p-6 bg-gray-50 min-h-[400px]">
          {currentStep === 1 && (
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
              <div className="mb-4">
                <h5 className="text-md font-semibold text-gray-800">Step 1: Patient Details</h5>
                <p className="text-sm text-gray-500">Enter the patient's vitals to prepare for AI analysis.</p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-4">
                <Form.Group>
                  <Form.Label className="text-sm font-medium text-gray-700">Full Name</Form.Label>
                  <Form.Control
                    type="text"
                    name="fullName"
                    value={formData.fullName}
                    onChange={handleChange}
                    isInvalid={!!errors.fullName}
                    placeholder="e.g. Jane Doe"
                    className="rounded-lg border-gray-200 focus:border-blue-500 focus:ring-blue-500"
                  />
                  <Form.Control.Feedback type="invalid" className="text-xs mt-1">{errors.fullName}</Form.Control.Feedback>
                </Form.Group>

                <Form.Group>
                  <Form.Label className="text-sm font-medium text-gray-700">Date of Birth</Form.Label>
                  <Form.Control
                    type="date"
                    name="dob"
                    value={formData.dob}
                    onChange={handleChange}
                    isInvalid={!!errors.dob}
                    max={new Date().toISOString().split('T')[0]}
                    className="rounded-lg border-gray-200 focus:border-blue-500 focus:ring-blue-500"
                  />
                  <Form.Control.Feedback type="invalid" className="text-xs mt-1">{errors.dob}</Form.Control.Feedback>
                </Form.Group>
              </div>

              <div className="mb-4">
                <Form.Group>
                  <Form.Label className="text-sm font-medium text-gray-700">Email Address</Form.Label>
                  <Form.Control
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    isInvalid={!!errors.email}
                    placeholder="jane.doe@example.com"
                    className="rounded-lg border-gray-200 focus:border-blue-500 focus:ring-blue-500"
                  />
                  <Form.Control.Feedback type="invalid" className="text-xs mt-1">{errors.email}</Form.Control.Feedback>
                </Form.Group>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-4">
                <Form.Group>
                  <Form.Label className="text-sm font-medium text-gray-700">Glucose (mg/dL)</Form.Label>
                  <Form.Control
                    type="number"
                    step="0.1"
                    name="glucose"
                    value={formData.glucose}
                    onChange={handleChange}
                    isInvalid={!!errors.glucose}
                    placeholder="e.g. 90"
                    className="rounded-lg border-gray-200 focus:border-blue-500 focus:ring-blue-500"
                  />
                  <Form.Control.Feedback type="invalid" className="text-xs mt-1">{errors.glucose}</Form.Control.Feedback>
                </Form.Group>

                <Form.Group>
                  <Form.Label className="text-sm font-medium text-gray-700">Haemoglobin (g/dL)</Form.Label>
                  <Form.Control
                    type="number"
                    step="0.1"
                    name="haemoglobin"
                    value={formData.haemoglobin}
                    onChange={handleChange}
                    isInvalid={!!errors.haemoglobin}
                    placeholder="e.g. 14.5"
                    className="rounded-lg border-gray-200 focus:border-blue-500 focus:ring-blue-500"
                  />
                  <Form.Control.Feedback type="invalid" className="text-xs mt-1">{errors.haemoglobin}</Form.Control.Feedback>
                </Form.Group>

                <Form.Group>
                  <Form.Label className="text-sm font-medium text-gray-700">Cholesterol (mg/dL)</Form.Label>
                  <Form.Control
                    type="number"
                    step="0.1"
                    name="cholesterol"
                    value={formData.cholesterol}
                    onChange={handleChange}
                    isInvalid={!!errors.cholesterol}
                    placeholder="e.g. 180"
                    className="rounded-lg border-gray-200 focus:border-blue-500 focus:ring-blue-500"
                  />
                  <Form.Control.Feedback type="invalid" className="text-xs mt-1">{errors.cholesterol}</Form.Control.Feedback>
                </Form.Group>
              </div>
            </div>
          )}

          {currentStep === 2 && (
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
              {isAnalyzing ? (
                <div className="text-center py-10">
                  <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600 mx-auto mb-4"></div>
                  <p className="text-gray-600 font-medium">Gemini is analyzing patient data...</p>
                  <p className="text-xs text-gray-400 mt-2">This usually takes a few seconds.</p>
                </div>
              ) : analyzeError ? (
                <div className="text-center py-10">
                  <div className="text-red-500 mb-2 flex justify-center">
                    <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                  </div>
                  <p className="text-red-600 font-medium">{analyzeError}</p>
                  <Button variant="outline-primary" onClick={handleAnalyze} className="mt-4">Try Again</Button>
                </div>
              ) : (
                renderHealthReport()
              )}
            </div>
          )}
        </Modal.Body>

        <Modal.Footer className="bg-white border-t border-gray-100 px-6 py-4 flex justify-between">
          {currentStep === 1 ? (
            <>
              <Button 
                variant="light" 
                onClick={onHide} 
                className="rounded-lg font-medium px-5 text-gray-600 bg-gray-100 hover:bg-gray-200 border-0"
              >
                Cancel
              </Button>
              <Button 
                variant="primary" 
                onClick={handleNextStep}
                className="rounded-lg font-medium px-5 shadow-sm bg-purple-600 hover:bg-purple-700 border-0 flex items-center gap-2"
              >
                ✨ Next: Analyze with Gemini
              </Button>
            </>
          ) : (
            <>
              <Button 
                variant="light" 
                onClick={() => setCurrentStep(1)} 
                className="rounded-lg font-medium px-5 text-gray-600 bg-gray-100 hover:bg-gray-200 border-0 flex items-center gap-2"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7"></path></svg>
                Back to Details
              </Button>
              <Button 
                variant="primary" 
                type="submit" 
                disabled={isAnalyzing}
                className="rounded-lg font-medium px-5 shadow-sm bg-blue-600 hover:bg-blue-700 border-0 ml-2"
              >
                Save Patient
              </Button>
            </>
          )}
        </Modal.Footer>
      </Form>
    </Modal>
  );
};

export default PatientModal;
